<script setup>
import PartnerLayout from '@/Layouts/PartnerLayout.vue';import Pagination from '@/Components/Partner/Pagination.vue';import FormErrors from '@/Components/Partner/FormErrors.vue';import {Link,useForm} from '@inertiajs/vue3';
defineProps({invoices:Object,customers:Array,plans:Array});const form=useForm({customer_uuid:'',plan_uuid:''});
</script>
<template><PartnerLayout title="Client invoices"><form class="form-card mb-6" @submit.prevent="form.post(route('partner.invoices.store'))"><h2 class="text-xl font-bold">Prepare a subscription invoice</h2><FormErrors :errors="form.errors"/><label>Client<select v-model="form.customer_uuid" required><option value="">Choose client</option><option v-for="client in customers" :key="client.uuid" :value="client.uuid">{{ client.name }}</option></select></label><label>Product and plan<select v-model="form.plan_uuid" required><option value="">Choose a plan</option><option v-for="plan in plans" :key="plan.uuid" :value="plan.uuid">{{ plan.product.name }} ? {{ plan.name }} ? {{ plan.currency }} {{ plan.price }} / {{ plan.billing_cycle }}</option></select></label><p class="text-sm text-slate-500">Catalogue prices exclude VAT. VAT of {{ Number($page.props.billing.vat_rate) }}% is added to the invoice and shown separately. Payment must be verified before the subscription activates.</p><button class="form-button" :disabled="form.processing||!customers.length||!plans.length">Create invoice</button></form><div class="space-y-3"><Link v-for="invoice in invoices.data" :key="invoice.uuid" :href="route('partner.invoices.show',invoice.uuid)" class="block rounded-xl bg-white p-5"><strong>{{ invoice.invoice_number }} ? {{ invoice.customer.name }}</strong><p class="mt-2 text-sm">{{ invoice.status }} ? {{ invoice.currency }} {{ invoice.total }} ? Balance {{ invoice.balance }}</p></Link><p v-if="!invoices.data.length">No invoices yet.</p></div><Pagination :page="invoices"/></PartnerLayout></template>
